const bedOffers=[{size:3,length:3,price:700,title:'Первый огород',text:'Небольшой участок, чтобы попробовать одну культуру.',counts:'Огурцы: 4–6 · томаты: 3–4 · баклажаны: 4–5 · кабачки: 2'},{size:7,length:7,price:1400,title:'Семейная грядка',text:'Больше места для любимой культуры или нескольких зон посадки.',counts:'Огурцы: 10–14 · томаты: 7–9 · баклажаны: 10–12 · кабачки: 4–5'}];
let selectedBedSize=null;
function offerCards(){return `<div class="grid">${bedOffers.map(p=>`<article class="panel"><small>${p.title}</small><h2>1 × ${p.length} м <small>· ${p.size} м²</small></h2><p>${p.text}</p><h3>${p.price.toLocaleString('ru-RU')} ₽ / месяц</h3><small>Демоаренда · уход и материалы отдельно</small><p><b>Если занять всю грядку одной культурой:</b></p><p>${p.counts} растений.</p><button class="btn" onclick="selectedBedSize=${p.size};location.hash='choose-bed';render();document.getElementById('available-beds')?.scrollIntoView({behavior:'smooth'})">Посмотреть участки ${p.size} м²</button></article>`).join('')}</div><p class="note">Количество растений — ориентир для одного ряда, огурцы и томаты на опорах. Это альтернативные посадки, их нельзя складывать. Сорт, проходы и способ формирования уточняет садовник; для кабачков нужно место для листьев за краями грядки. Урожай в килограммах не гарантируется. <a href="https://extension.umaine.edu/gardening/manual__trashed/planting-chart-home-vegetable-garden/" target="_blank" rel="noopener">Рекомендации по расстояниям</a>. Аренда оплачивается демосредствами. Размеры участков в тестовом каталоге требуют проверки на ферме.</p>`}
const homeBeforeOnboarding=cloudHome;
function emptyFarm(){const plots=cloud?.plots||[];return `<section class="panel empty-farm"><span class="eyebrow">МОЁ ХОЗЯЙСТВО</span><h1>${account&&myPlots().length?'Добавьте грядку в хозяйство':'Пока у вас нет грядок'}</h1><a class="btn" href="#choose-bed">Приобрести грядку</a><p>Выберите город и размер — участок подберём сами.</p></section>`}
cloudHome=function(){if(!myPlots().length)return emptyFarm();return homeBeforeOnboarding()+`<section class="panel"><h2>Моя аренда</h2>${(cloud.rentals||[]).map(r=>`<div class="event"><b>Грядка №${r.plot_id} · ${r.is_simulation?'демоаренда':'аренда'}</b><p>${r.ends_at?'До '+fmt(r.ends_at):'Срок уточняется'} · ${money(r.price_kopecks||0)}${r.ends_at&&new Date(r.ends_at)<new Date()?' · Срок истёк, обратитесь к управляющему':''}</p></div>`).join('')}</section>`};
let rentalCity=null;
const rentalCities=[{id:'moscow',name:'Москва',icon:'🏙️',ready:false},{id:'krasnodar',name:'Краснодар',icon:'☀️',ready:true},{id:'petersburg',name:'Санкт-Петербург',icon:'🌉',ready:false}];
function sizeOffers(){const available=(cloud?.plots||[]).filter(p=>p.status==='available'&&!p.mine&&p.rental_simulation&&p.rental_monthly_kopecks);return [...new Map(available.map(p=>[p.size+':'+p.rental_monthly_kopecks,{size:Number(p.size),price:Number(p.rental_monthly_kopecks)}])).values()].sort((a,b)=>a.size-b.size||a.price-b.price)}
rent=function(){if(!rentalCity)return heading('Где будет ваша грядка?','Сначала выберите город, затем удобный размер.')+`<div class="grid">${rentalCities.map(c=>`<section class="panel"><span style="font-size:38px">${c.icon}</span><h2>${c.name}</h2><p>${c.ready?'Ферма в Белореченске, Краснодарский край':'Ферма пока не подключена'}</p><button class="btn" ${c.ready?'':'disabled'} onclick="rentalCity='${c.id}';render()">${c.ready?'Выбрать город':'Скоро'}</button></section>`).join('')}</div>`;const offers=sizeOffers();return `<button class="btn light" onclick="rentalCity=null;render()">← Выбрать другой город</button>`+heading('Выберите размер грядки','Краснодар · ферма в Белореченске. Конкретный участок назначим автоматически.')+(!account?'<section class="panel"><p>Войдите, чтобы увидеть размеры и актуальную стоимость.</p><button class="btn" onclick="profile()">Войти / регистрация</button></section>':offers.length?`<div class="grid">${offers.map(o=>{const info=bedOffers.find(x=>x.size===o.size);return `<article class="panel"><small>${info?.title||'Своя грядка'}</small><h2>${o.size} м²${info?' · 1 × '+info.length+' м':''}</h2><p>${info?.text||'Площадь для ваших посадок.'}</p><h3>${money(o.price)} / месяц</h3><p>Уход, материалы и доставка оплачиваются отдельно.</p><button class="btn" onclick="rentBySize(${o.size},${o.price})">Арендовать ${o.size} м²</button></article>`}).join('')}</div>`:'<section class="panel"><h2>Сейчас все грядки заняты</h2><p>Ферма сможет открыть аренду, когда подготовит новые участки.</p><button class="btn light" onclick="refreshCloud().catch(e=>toast(e.message))">Проверить наличие</button></section>')+'<p class="note">Оплата тестовыми средствами. Номер грядки появится в хозяйстве после оформления.</p>'};
function rentBySize(size,price){const key=crypto.randomUUID();formAsync('Аренда грядки · '+size+' м²',`<p>Краснодар · ферма в Белореченске</p><h3>${money(price)} / месяц</h3><label>Срок<select name="months" onchange="document.getElementById('rental-total').textContent=money(${price}*Number(this.value))">${[1,2,3,6,12].map(n=>`<option value="${n}">${n} мес.</option>`).join('')}</select></label><p>Итого: <strong id="rental-total">${money(price)}</strong></p><p>Свободный участок этого размера назначим автоматически после оплаты. Уход и материалы отдельно.</p><p class="note">Демоаренда. Реальные деньги не списываются. Автопродления нет.</p><p><a href="#wallet" onclick="modal.close()">Пополнить демобаланс</a></p><button class="btn">Оплатить демобалансом и арендовать</button>`,async f=>{await api('claim',{city:rentalCity,size,price,months:Number(f.get('months')),key});await refreshCloud();location.hash='home';toast('Грядка появилась в вашем хозяйстве')})}

const beforeOnboardingRender=render;render=function(){beforeOnboardingRender();const route=location.hash.slice(1)||'home';if(route==='rent'||route==='home'&&(!account||!myPlots().length)){$('#app').innerHTML=emptyFarm();$('#crumb').textContent='МОЁ ХОЗЯЙСТВО'}if(route==='choose-bed'){$('#app').innerHTML=rent();$('#crumb').textContent='ВЫБОР ГРЯДКИ'}};render();
